insert into public.answer_key_items (scenario_id, code, at_label, behaviour, kind, strong_debrief, sort) select id, 'A2', '1:00', '“Your AHT has been over target all month”', 'subtle_miss', 'Wrong: the rise starts in W4 and is team-wide, so the premise is unfair', 1 from public.scenarios where family = 'rec-coaching' and version = 'A';
